sql_query:
SELECT "Control regimen"
FROM clinical_trials
WHERE "Cancer type" = 'Non-Small Cell Lung' AND "Control arm" = 'Chemo' AND "Included in MA" = 'No' AND "Trial phase" = 'Phase 3';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Control regimen" AS source_value FROM clinical_trials WHERE "Cancer type" = 'Non-Small Cell Lung' AND "Control arm" = 'Chemo' AND "Included in MA" = 'No' AND "Trial phase" = 'Phase 3'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_specific_regimens(source_value) AS "specific_regimens"
FROM base;
